7638      private void castToTypeBelow(Expr expr, Type declared) {
7639          if (!(declared instanceof TraitType || declared instanceof VarType)) return;
7640          Option<Type> ot = expr.getInfo().getExprType();
7641          if (ot.isNone()) return;
7642          Type t = ot.unwrap();
7643          if (t instanceof com.sun.fortress.nodes.UnionType) {
7644              // A typecase has the union of its arms' types: self's type where each arm has it.
7645              Type one = null;
7646              for (Type e : ((com.sun.fortress.nodes.UnionType) t).getElements()) {
7647                  if (e instanceof BottomType) continue;
7648                  if (one != null && !one.equals(e)) return;
7649                  one = e;
7650              }
7651              t = one;
7652          }
7653          if (!(t instanceof TraitSelfType)) return;
7654          TraitSelfType self_t = (TraitSelfType) t;
7655          Type apparent = self_t.getNamed();
7656          if (self_t.getComprised().isEmpty() || !(apparent instanceof TraitType)) return;
7657          if (typeAnalyzer.opensSizes(apparent)) return;
7658          if (typeAnalyzer.lteq(apparent, declared) || !typeAnalyzer.lteq(declared, apparent)) return;
7659          String cast_to = NamingCzar.jvmTypeDesc(declared, thisApi(), false, true);
7660          InstantiatingClassloader.generalizedCastTo(mv, cast_to);
7661      }

